  M("A", "formulae", "What is the formula for Profit?", "Total revenue - total costs", ["Cost of sales / average inventories held", "Full years + (amount still to recover / net cash flow in the next year)", "% change in quantity demanded / % change in price"], "Profit = Total revenue - total costs");
  M("A", "formulae", "What is the formula for Total costs?", "Fixed costs + variable costs", ["Average annual profit / initial investment x 100", "Non-current liabilities / capital employed x 100", "Cost of sales / average inventories held"], "Total costs = Fixed costs + variable costs");
  M("A", "formulae", "What is the formula for Market share (%)?", "Business sales / total market sales x 100", ["% change in quantity demanded / % change in income", "Profit for the year / revenue x 100", "Selling price - variable cost per unit"], "Market share (%) = Business sales / total market sales x 100");
  M("A", "formulae", "What is the formula for Market / sales growth (%)?", "(New value - old value) / old value x 100", ["Operating profit / capital employed x 100", "Total equity + non-current liabilities", "Latest finish time - duration - earliest start time"], "Market / sales growth (%) = (New value - old value) / old value x 100");
  M("A", "formulae", "What is the formula for PED?", "% change in quantity demanded / % change in price", ["(New value - old value) / old value x 100", "Selling price - cost of bought-in materials", "Cost of sales / average inventories held"], "PED = % change in quantity demanded / % change in price");
  M("A", "formulae", "What is the formula for YED?", "% change in quantity demanded / % change in income", ["(New value - old value) / old value x 100", "Full years + (amount still to recover / net cash flow in the next year)", "Non-current liabilities / capital employed x 100"], "YED = % change in quantity demanded / % change in income");
  M("B", "formulae", "What is the formula for Labour productivity?", "Output per period / number of employees", ["Receivables / revenue x 365", "Actual output / maximum possible output x 100", "Latest finish time - duration - earliest start time"], "Labour productivity = Output per period / number of employees");
  M("A", "formulae", "What is the formula for Re-order level?", "(Usage per day x lead time) + buffer inventory", ["Cost of sales / average inventories held", "Profit for the year / revenue x 100", "Sum of (probability x financial outcome)"], "Re-order level = (Usage per day x lead time) + buffer inventory");
  M("A", "formulae", "What is the formula for Added value?", "Selling price - cost of bought-in materials", ["Number leaving / average number employed x 100", "(Usage per day x lead time) + buffer inventory", "Number of shares x share price"], "Added value = Selling price - cost of bought-in materials");
  M("A", "formulae", "What is the formula for Gross profit margin (%)?", "Gross profit / revenue x 100", ["Payables / cost of sales x 365", "Average annual profit / initial investment x 100", "(Usage per day x lead time) + buffer inventory"], "Gross profit margin (%) = Gross profit / revenue x 100");
  M("A", "formulae", "What is the formula for Operating profit margin (%)?", "Operating profit / revenue x 100", ["Actual output / maximum possible output x 100", "Receivables / revenue x 365", "Number leaving / average number employed x 100"], "Operating profit margin (%) = Operating profit / revenue x 100");
  M("A", "formulae", "What is the formula for Profit for the year margin (%)?", "Profit for the year / revenue x 100", ["Actual output / maximum possible output x 100", "Non-current liabilities / capital employed x 100", "Total costs / units of output"], "Profit for the year margin (%) = Profit for the year / revenue x 100");
  M("A", "formulae", "What is the formula for Contribution per unit?", "Selling price - variable cost per unit", ["Latest finish time - duration - earliest start time", "Employee costs / revenue x 100", "Total costs / units of output"], "Contribution per unit = Selling price - variable cost per unit");
  M("A", "formulae", "What is the formula for Margin of safety?", "Actual output - break-even output", ["Receivables / revenue x 365", "Employee costs / revenue x 100", "Current assets : current liabilities"], "Margin of safety = Actual output - break-even output");
  M("A", "formulae", "What is the formula for Variance?", "Actual - budget (adverse if it reduces profit)", ["% change in quantity demanded / % change in income", "Number of shares x share price", "Sum of (probability x financial outcome)"], "Variance = Actual - budget (adverse if it reduces profit)");
  M("B", "formulae", "What is the formula for Labour turnover (%)?", "Number leaving / average number employed x 100", ["Output per period / number of employees", "Current assets : current liabilities", "Number of shares x share price"], "Labour turnover (%) = Number leaving / average number employed x 100");
  M("A", "formulae", "What is the formula for Labour cost per unit?", "Labour costs / units of output", ["Fixed costs / contribution per unit", "% change in quantity demanded / % change in price", "Selling price - variable cost per unit"], "Labour cost per unit = Labour costs / units of output");
  M("A", "formulae", "What is the formula for ROCE (%)?", "Operating profit / capital employed x 100", ["% change in quantity demanded / % change in price", "Operating profit / revenue x 100", "Fixed costs + variable costs"], "ROCE (%) = Operating profit / capital employed x 100");
  M("A", "formulae", "What is the formula for Capital employed?", "Total equity + non-current liabilities", ["Number of shares x share price", "Receivables / revenue x 365", "Latest finish time - duration - earliest start time"], "Capital employed = Total equity + non-current liabilities");
  M("A", "formulae", "What is the formula for Current ratio?", "Current assets : current liabilities", ["Number of shares x share price", "% change in quantity demanded / % change in price", "(New value - old value) / old value x 100"], "Current ratio = Current assets : current liabilities");
  M("A", "formulae", "What is the formula for Gearing (%)?", "Non-current liabilities / capital employed x 100", ["(New value - old value) / old value x 100", "(Usage per day x lead time) + buffer inventory", "Actual output - break-even output"], "Gearing (%) = Non-current liabilities / capital employed x 100");
  M("B", "formulae", "What is the formula for Inventory turnover?", "Cost of sales / average inventories held", ["Employee costs / revenue x 100", "Business sales / total market sales x 100", "Number leaving / average number employed x 100"], "Inventory turnover = Cost of sales / average inventories held");
  M("A", "formulae", "What is the formula for Receivables days?", "Receivables / revenue x 365", ["Cost of sales / average inventories held", "Operating profit / revenue x 100", "Non-current liabilities / capital employed x 100"], "Receivables days = Receivables / revenue x 365");
  M("A", "formulae", "What is the formula for Payables days?", "Payables / cost of sales x 365", ["(New value - old value) / old value x 100", "Sum of (probability x financial outcome)", "Full years + (amount still to recover / net cash flow in the next year)"], "Payables days = Payables / cost of sales x 365");
  M("C", "formulae", "What is the formula for Payback?", "Full years + (amount still to recover / net cash flow in the next year)", ["Total costs / units of output", "Business sales / total market sales x 100", "Sum of (probability x financial outcome)"], "Payback = Full years + (amount still to recover / net cash flow in the next year)");
  M("A", "formulae", "What is the formula for ARR (%)?", "Average annual profit / initial investment x 100", ["Selling price - variable cost per unit", "Non-current liabilities / capital employed x 100", "Receivables / revenue x 365"], "ARR (%) = Average annual profit / initial investment x 100");
  M("C", "formulae", "What is the formula for NPV?", "Sum of (net cash flow x discount factor) - initial investment", ["Employee costs / revenue x 100", "Gross profit / revenue x 100", "Total revenue - total costs"], "NPV = Sum of (net cash flow x discount factor) - initial investment");
  M("B", "formulae", "What is the formula for Total float?", "Latest finish time - duration - earliest start time", ["Labour costs / units of output", "Current assets : current liabilities", "Selling price - cost of bought-in materials"], "Total float = Latest finish time - duration - earliest start time");
  M("A", "Understanding management decision making", "Intuitive (hunch-based) decision making is most likely to be appropriate when:", "a decision must be made quickly in an unprecedented situation", ["reliable historical data is available", "the decision is routine and repeated", "the business is risk averse"], "When there is no reliable data and little time (e.g. a new, fast-moving situation), experience and intuition may be the only practical basis for a decision.");
